/* @lc app=leetcode id=3408 lang=kotlin */ class TaskManager(tasks: List<List<Int>>, val m: HashMap<Int, IntArray> = HashMap(), val ts: java.util.TreeSet<Long> = java.util.TreeSet(), val init: Unit = tasks.forEach { t -> m.put(t[1], intArrayOf(t[0], t[2])).let { ts.add((t[2].toLong() shl 20) or t[1].toLong()) } }) { fun add(userId: Int, taskId: Int, priority: Int) { m.put(taskId, intArrayOf(userId, priority)).let { ts.add((priority.toLong() shl 20) or taskId.toLong()) } } fun edit(taskId: Int, newPriority: Int) { m[taskId]?.let { ts.remove((it[1].toLong() shl 20) or taskId.toLong()).let { _ -> it[1] = newPriority }.let { _ -> ts.add((newPriority.toLong() shl 20) or taskId.toLong()) } } } fun rmv(taskId: Int) { m.remove(taskId)?.let { ts.remove((it[1].toLong() shl 20) or taskId.toLong()) } } fun execTop(): Int = ts.pollLast()?.let { k -> m.remove((k and 0xFFFFF).toInt())!![0] } ?: -1 }